INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 15, 'theory', 'Quiz: ownership');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 0, 'What happens after let t = s; if s is a String?', '["Both variables point to one buffer and both stay usable", "The three words of s are copied into t, and s becomes invalid", "The string is copied entirely into a new buffer", "The program compiles but crashes at runtime"]', 1, 'Assignment transfers ownership: the pointer, length and capacity are copied on the stack, and the name s can no longer be used. Otherwise the buffer would be freed twice at the brace.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 1, 'Which of these types can be copied bitwise (implements Copy)?', '["String", "Vec<i32>", "Box<i32>", "(i32, f64, char)"]', 3, 'Copy is available to types that live entirely on the stack and own nothing on the heap: numbers, bool, char, and tuples or arrays of them. String, Vec and Box own heap memory.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 2, 'In what order are a block''s variables destroyed at the closing brace?', '["In reverse order of declaration", "In order of declaration", "In arbitrary order", "All at once, the order is undefined"]', 0, 'The last one created dies first, like frames on the stack. That is why dependent values can be created after the ones they depend on.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 3, 'Why is Box needed in the definition enum List { Cons(i32, Box<List>), Nil }?', '["To make the list faster", "To make the values copyable", "To make the type size finite: inside there is a pointer, not a List itself", "So that elements are removed by a garbage collector"]', 2, 'Without Box the type would contain itself and have infinite size (error E0072). A pointer takes 8 bytes, and the rest of the chain lives on the heap.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 15, 4, 'What does Rc::clone(&a) do?', '["Copies the value into a new buffer", "Copies the pointer and increases the owner count", "Transfers ownership and zeroes a", "Creates a weak reference without a counter"]', 1, 'The data is not duplicated: one more owner of the same value appears, and strong_count grows by one. The value is destroyed when the last owner leaves.');
